from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

root = Path('products/services/nz-gets-data-acceptance-pilot')
raw = (root / 'raw/official-entry.html').read_bytes()
base = 'https://www.gets.govt.nz/ExternalIndex.htm'
expected = '13f28798910a72034404d8258095e249ad6f24d36eba3351ff69ddfa15f1d05f'
digest = hashlib.sha256(raw).hexdigest()
assert digest == expected, 'Capture differs from official GETS retrieval receipt'

def compact(parts):
    return ' '.join(' '.join(parts).split())

class Entry(HTMLParser):
    def __init__(self):
        super().__init__()
        self.anchor = None
        self.row = None
        self.cell = None
        self.links = []
        self.rows = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag in ('a', 'link') and attrs.get('href'):
            self.anchor = (attrs['href'], [attrs.get('title', ''), attrs.get('rel', '')])
            if tag == 'link':
                self.handle_endtag('a')
        elif tag == 'tr':
            self.row = {'cells': [], 'links': []}
        elif tag in ('td', 'th') and self.row is not None:
            self.cell = []

    def handle_data(self, value):
        if self.anchor is not None:
            self.anchor[1].append(value)
        if self.cell is not None:
            self.cell.append(value)

    def handle_endtag(self, tag):
        if tag == 'a' and self.anchor is not None:
            href, label = self.anchor
            self.anchor = None
            url = urljoin(base, href)
            parsed = urlsplit(url)
            if not href.startswith('#') and parsed.scheme == 'https' and parsed.hostname in ('www.gets.govt.nz', 'gets.govt.nz'):
                link = {'label': compact(label)[:240], 'url': url}
                self.links.append(link)
                if self.row is not None:
                    self.row['links'].append(link)
        elif tag in ('td', 'th') and self.cell is not None:
            self.row['cells'].append(compact(self.cell)[:280])
            self.cell = None
        elif tag == 'tr' and self.row is not None:
            self.rows.append(self.row)
            self.row = None

def matches(link, pattern):
    return bool(re.search(pattern, link['label'] + ' ' + link['url'], re.I))

page = Entry()
page.feed(raw.decode('utf-8', errors='replace'))
page.close()
notice_pattern = r'ExternalTenderDetails|id=\d+.*tender'
feed_pattern = r'\brss\b|\batom\b|\bfeed\b|current tenders|open opportunities|current opportunities'
date_pattern = r'\b(?:20\d{2}[-/]\d{1,2}[-/]\d{1,2}|\d{1,2}[-/]\d{1,2}[-/]20\d{2}|\d{1,2}\s+[A-Za-z]{3,9}\s+20\d{2})\b'
fit_pattern = r'\b(?:data quality|data cleansing|data migration|data validation|spreadsheet|catalogue|records digitisation|data reconciliation)\b'
notices = list({link['url']: link for link in page.links if matches(link, notice_pattern)}.values())
feeds = list({link['url']: link for link in page.links if matches(link, feed_pattern)}.values())
notice_rows = [row for row in page.rows if any(matches(link, notice_pattern) for link in row['links'])]
dated_rows = [row for row in notice_rows if re.search(date_pattern, ' '.join(row['cells']))]
plausible_rows = [row for row in notice_rows if re.search(fit_pattern, ' '.join(row['cells']), re.I)]
result = {'receipt': 'TASK-179530920201', 'source': base, 'sha256': digest, 'scope': 'Structural readback of one fetched entry page. Dates are verbatim row text and may be publication dates. Links and keywords do not establish open status, buyer eligibility, a permitted response route or market coverage.', 'direct_notice_count': len(notices), 'notice_rows_with_visible_date_count': len(dated_rows), 'scope_keyword_row_count': len(plausible_rows), 'unverified_scope_candidates': plausible_rows[:10], 'dated_notice_examples': dated_rows[:3], 'first_party_discovery_links': feeds[:12], 'direct_notice_examples': notices[:5]}
out = root / 'director-entry-structure.json'
out.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
